Add({
	kind = "figure",
	id = "sage-truthseeker",
	title = "Sage Truthseeker",
	aliases = { "Truthseeker" },
	subtitle = "Sage of Thunder Bluff",
	tier = "B",
	region = "thunder-bluff",
	npc = { 3978 },
	allegiance = "Thunder Bluff · The Sages",
	found = "The lower rise of Thunder Bluff",
	pin = { x = 34.4, y = 46.9 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Seek the sage who gathers the lost knowledge of Azeroth for the tauren.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Sage Truthseeker is one of the sages of {link:thunder-bluff}Thunder Bluff{/link}, the historians of the {link:tauren}tauren{/link}. He gathers old books, relics and secrets from across the world and studies them for his people. He would trust {link:cairne-bloodhoof}Cairne{/link} with his life. He does not trust the {link:forsaken}Forsaken{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[The Sage speaks for the {link:tauren}tauren{/link} who doubt the pact with the dead. He believes that the {link:earthen-ring}Earthen Ring{/link} meant well when it urged the {link:horde}Horde{/link} to help them, but he wonders who was whispering in the ears of its Elder Council. He also stands at the edge of a deeper mystery, one that reaches back to the makers of the world.]=],
		},
		{
			title = "Deeds",
			text = [=[• He sought the Compendium of the Fallen from the zealots of the {link:scarlet-monastery}Scarlet Monastery{/link}.
• He studies the discs of Norgannon brought back from {link:uldaman}Uldaman{/link}.
• He and {link:nara-wildmane}Nara Wildmane{/link} follow the discs toward {link:valley-of-the-watchers}Uldum{/link}.]=],
		},
	},
	chapters = {
		{
			key = "compendium-of-the-fallen",
			title = "Compendium of the Fallen",
			hint = "Bring the Sage the book the Scarlet zealots guard.",
			unlock = {
				{ type = "quest", id = 1049 },
			},
			text = [=[The {link:forsaken}Forsaken{/link} have a history full of deceit, the Sage says, and the pact was made too quickly. Perhaps {link:cairne-bloodhoof}Cairne{/link} should have heeded the warnings from {link:orgrimmar}Orgrimmar{/link}. The zealots of the {link:scarlet-crusade}Scarlet Crusade{/link} are mad, but they have studied the undead, and Truthseeker wanted to know what they had learned. He had begun to wonder if their book existed at all.]=],
		},
		{
			key = "the-platinum-discs",
			title = "The Platinum Discs",
			hint = "Bring the Sage a relic from the vaults of Uldaman.",
			unlock = {
				{ type = "quest", id = 2280 },
			},
			text = [=[From {link:uldaman}Uldaman{/link} came a miniature copy of the platinum discs of Norgannon. The Sage sensed in them secrets that the earth had held tightly for ages. He set himself to learn how they worked, and promised that they would reveal themselves in time.]=],
		},
		{
			key = "portents-of-uldum",
			title = "Portents of Uldum",
			hint = "Follow the translated glyphs of the discs.",
			unlock = {
				{ type = "quest", id = 2965 },
			},
			text = [=[The glyphs on the discs spoke of a place called {link:valley-of-the-watchers}Uldum{/link}, which most believe a myth. Truthseeker brought the matter to {link:nara-wildmane}Nara Wildmane{/link}, who had seen the sealed gates in the Valley of the Watchers in {link:tanaris}Tanaris{/link}. Together they decided that the discs and Uldum were bound together.]=],
		},
	},
	mentions = {
		{
			text = "The Platinum Discs",
			unlock = {
				{ type = "quest", id = 2440 },
			},
		},
		{
			text = "Seeing What Happens",
			unlock = {
				{ type = "quest", id = 2966 },
			},
		},
		{
			text = "A Future Task",
			unlock = {
				{ type = "quest", id = 2968 },
			},
		},
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "whom he would trust with his life" },
		{ id = "nara-wildmane", name = "Nara Wildmane", note = "shares his study of Uldum" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "champion of the pact he distrusts" },
	},
})

